  if (onCompletionIntent && eligible.has('completeAgentSession')) {
    available.push({
      name: 'workmesh_complete_session', label: 'workmesh complete session',
      description: 'Request completion of this exact Session. Give an evidence-backed summary and current Session revision. The Runner commits completion only after its public answer is durably settled; verify the final Session state afterward.',
      parameters: Type.Object({ ifMatch: Type.Integer({ minimum: 1 }),
        summary: Type.String({ minLength: 1, maxLength: 20_000 }),
        artifactIds: Type.Optional(Type.Array(idParameter, { maxItems: 100 })),
        checks: Type.Optional(Type.Array(Type.Object({ name: Type.String({ minLength: 1, maxLength: 160 }),
          command: Type.Optional(Type.String({ maxLength: 10_000 })),
          status: Type.Union([Type.Literal('passed'), Type.Literal('failed'), Type.Literal('skipped')]),
          summary: Type.String({ minLength: 1, maxLength: 10_000 }) }), { maxItems: 100 })),
        limitations: Type.Optional(Type.Array(Type.String({ minLength: 1, maxLength: 2000 }), { maxItems: 100 })),
        noArtifactReason: Type.Optional(Type.String({ minLength: 1, maxLength: 2000 })) }),
      execute: async (toolCallId, input, signal) => {
        onCall('workmesh_complete_session')
        if (signal?.aborted) throw new Error('RUNNER_ABORTED')
        const { ifMatch, ...body } = z.object({ ifMatch: z.number().int().positive(),
          summary: z.string(), artifactIds: z.array(id).optional(),
          checks: z.array(z.unknown()).optional(), limitations: z.array(z.string()).optional(),
          noArtifactReason: z.string().optional() }).parse(input)
        const intent: SessionCompletionIntent = {
          body: completeAgentSessionInputSchema.parse(body), ifMatch,
          idempotencyKey: operationKey(api.sessionId, attemptId, toolCallId, 'completeAgentSession'),
        }
        onCompletionIntent(intent)
        return { content: [{ type: 'text' as const, text: boundedResult({
          status: 'queued_after_turn_settlement', sessionId: api.sessionId,
          message: 'Completion is pending. Give the user a public answer; then inspect the Session state.',
        }) }], details: { source: 'workmesh_runner', operationId: 'completeAgentSession',
          operationKey: intent.idempotencyKey } }
      },
    })
  }
  if (onFailureIntent && eligible.has('failAgentSession')) {
    available.push({
      name: 'workmesh_fail_session', label: 'workmesh fail session',
      description: 'Request failure of this exact Session. Stops further model tools. The Runner first durably fails this Turn, then calls the existing Session fail command as a separate transaction. Neither request acknowledgment nor Turn failure proves Session failure.',
      parameters: Type.Object({ifMatch:Type.Integer({minimum:1}),code:Type.String({minLength:1,maxLength:120}),
        summary:Type.String({minLength:1,maxLength:20000}),retryable:Type.Optional(Type.Boolean()),
        evidence:Type.Optional(Type.Array(Type.String({minLength:1,maxLength:2000}),{maxItems:100}))}),
      execute: async (toolCallId,input,signal) => {
        onCall('workmesh_fail_session')
        if (signal?.aborted) throw new Error('RUNNER_ABORTED')
        const {ifMatch,...body}=z.object({ifMatch:z.number().int().positive(),code:z.string(),summary:z.string(),
          retryable:z.boolean().optional(),evidence:z.array(z.string()).optional()}).strict().parse(input)
        const intent:SessionFailureIntent={body:failAgentSessionInputSchema.parse(body),ifMatch,
          idempotencyKey:operationKey(api.sessionId,attemptId,toolCallId,'failAgentSession')}
        onFailureIntent(intent)
        return {content:[{type:'text' as const,text:boundedResult({status:'requested_after_failed_turn_settlement',sessionId:api.sessionId,
          message:'Session failure is pending; inspect durable Session and Turn states separately.'})}],
          details:{source:'workmesh_runner',operationId:'failAgentSession',operationKey:intent.idempotencyKey}}
      },
    })
  }
  return available
}

import { createHash, randomUUID } from 'node:crypto'
import { afterAll, afterEach, beforeAll, beforeEach, describe, expect, it } from 'vitest'
import { applyMigrations, createDb, opaqueToken, tokenHash, admitAutomationOccurrence, withTx } from '@workmesh/db'
import { loadFeatureConfig } from '@workmesh/config'
import { createAutomationWorker } from '../../worker/src/automation.js'
import { buildApp } from '../src/server.js'
import { seedAgentSessionBearer } from './agent-session-test-credentials.js'

const databaseUrl = process.env.DATABASE_URL
if (process.env.RUN_INTEGRATION !== '1' || !databaseUrl) throw new Error('Stage 2 API integration requires RUN_INTEGRATION=1 and DATABASE_URL.')
if (!/(^|[_-])test(?:[_-]|$)/i.test(new URL(databaseUrl).pathname.slice(1))) throw new Error('Stage 2 API integration requires a dedicated *test* database.')

const db = createDb(databaseUrl)
const restoreSessionSubjectConstraint = async (): Promise<void> => {
  const exists = await db.query(
    `SELECT 1 FROM pg_constraint
      WHERE conname='agent_sessions_scope_kind_check'
        AND conrelid='agent_sessions'::regclass`,
  )
  if (exists.rowCount) return
  await db.query(
    'ALTER TABLE agent_sessions DROP CONSTRAINT IF EXISTS agent_sessions_subject_container_check',
  )
  await db.query(
    'UPDATE agent_sessions SET project_id=NULL WHERE work_item_id IS NOT NULL',
  )
  await db.query(`
    ALTER TABLE agent_sessions
      ADD CONSTRAINT agent_sessions_scope_kind_check CHECK (
        (session_kind='coordination' AND automation_run_id IS NULL AND parent_session_id IS NULL
          AND num_nonnulls(work_item_id,project_id,plan_step_id)=0)
        OR (session_kind='execution' AND (
          (automation_run_id IS NOT NULL AND parent_session_id IS NULL
            AND num_nonnulls(work_item_id,project_id,plan_step_id)=0)
          OR (automation_run_id IS NULL AND (
            (parent_session_id IS NULL AND num_nonnulls(work_item_id,project_id,plan_step_id)=1)
            OR (parent_session_id IS NOT NULL AND num_nonnulls(work_item_id,project_id)=1)
          ))
        ))
      )`)
}
type Page<T> = { items: T[]; nextCursor: string | null }
const app = buildApp()
type Response = { statusCode: number; headers: Record<string, string | string[] | number | undefined>; json: <T>() => T }
type Human = { cookie: string; csrf: string; actorId: string }
type Agent = { id: string; actorId: string; installationToken: string }
type Session = { id: string; revision: number }
type Fixture = { human: Human; workspaceId: string; teamId: string; readyId: string; workItemId: string; parent: Session; parentToken: string; runner: Agent; reviewer: Agent; overflow: Agent; planVersionId: string; stepA: string; stepB: string; stepC: string }

const humanCall = async (human: Human, method: 'DELETE' | 'GET' | 'PATCH' | 'POST' | 'PUT', url: string, payload?: object, extra: Record<string, string> = {}): Promise<Response> =>
  await app.inject({ method, url, payload, headers: { cookie: human.cookie, 'x-csrf-token': human.csrf, 'idempotency-key': randomUUID(), ...extra } }) as unknown as Response
const agentCall = async (token: string, method: 'GET' | 'POST' | 'PUT', url: string, payload?: object, extra: Record<string, string> = {}): Promise<Response> =>
  await app.inject({ method, url, payload, headers: { authorization: `Bearer ${token}`, 'idempotency-key': randomUUID(), ...extra } }) as unknown as Response

async function register(human: Human, teamId: string, slug: string): Promise<Agent> {
  const response = await humanCall(human, 'POST', '/api/v1/agents/register', { name: slug, slug, provider: 'fake', version: '1', supportedProtocols: ['native_http'], requestedCapabilities: ['work:read', 'work:write', 'plan:write', 'artifact:write'], approvedCapabilities: ['work:read', 'work:write', 'plan:write', 'artifact:write'], maxConcurrency: 2 })
  expect(response.statusCode).toBe(200)
  const created = response.json<{ id: string; installation_token: string }>()
  expect((await humanCall(human, 'PUT', `/api/v1/agents/${created.id}/team-access/${teamId}`, { approvedCapabilities: ['work:read', 'work:write', 'plan:write', 'artifact:write'] })).statusCode).toBe(200)
  const row = await db.query<{ actor_id: string }>('SELECT actor_id FROM agent_definitions WHERE id=$1', [created.id])
  return { id: created.id, actorId: row.rows[0]!.actor_id, installationToken: created.installation_token }
}

async function registerWithoutTeamAccess(human: Human, slug: string): Promise<Agent> {
  const response = await humanCall(human, 'POST', '/api/v1/agents/register', { name: slug, slug, provider: 'fake', version: '1', supportedProtocols: ['native_http'], requestedCapabilities: ['work:read', 'work:write'], approvedCapabilities: ['work:read', 'work:write'], maxConcurrency: 2 })
  expect(response.statusCode).toBe(200)
  const created = response.json<{ id: string; installation_token: string }>()
  const row = await db.query<{ actor_id: string }>('SELECT actor_id FROM agent_definitions WHERE id=$1', [created.id])
  return { id: created.id, actorId: row.rows[0]!.actor_id, installationToken: created.installation_token }
}

async function start(human: Human, agent: Agent, _workspaceId: string, _teamId: string, workItemId: string, budget: Record<string, number> = {}): Promise<Session> {
  const revision = (await db.query<{ revision: number }>(
    'SELECT revision FROM work_items WHERE id=$1',
    [workItemId],
  )).rows[0]!.revision
  const response = await humanCall(human, 'POST', `/api/v1/work-items/${workItemId}/agent-session`, {
    agentId: agent.id,
    principalHumanActorId: human.actorId,
    role: 'executor',
    requestedCapabilities: ['work:read', 'work:write', 'plan:write', 'artifact:write'],
    initialPrompt: 'Stage 2 integration',
    budget,
  }, { 'if-match': `"revision-${revision}"` })
  expect(response.statusCode).toBe(200)
  return response.json<{ session: Session }>().session
}

async function exchangeAndExecute(session: Session, agent: Agent): Promise<string> {
  const token = await seedAgentSessionBearer(db, session.id, agent.id)
  const ack = await agentCall(token, 'POST', `/api/v1/agent-sessions/${session.id}/ack`, { summary: 'accepted', externalUrls: [] })
  expect(ack.statusCode).toBe(200)
  const state = await agentCall(token, 'POST', `/api/v1/agent-sessions/${session.id}/state`, { state: 'executing', reason: 'integration' }, { 'if-match': `"revision-${ack.json<{ revision: number }>().revision}"` })
  expect(state.statusCode).toBe(200)
  return token
}

async function exchangeOnly(session: Session, agent: Agent): Promise<string> {
  return seedAgentSessionBearer(db, session.id, agent.id)
}

