  constructor(message: string, options: { code: WorkMeshErrorCode; status?: number; correlationId?: string; details?: unknown; retry?: WorkMeshRetryMetadata }) {
    super(message)
    this.name = 'WorkMeshSdkError'
    this.code = options.code
