      .strict(),
    skill: agentConnectionSkillBundleSchema,
    principal_human_actor_id: idSchema,
    team_id: idSchema,
    idempotency_replay: z
      .object({
        replayable_until: timestampSchema,
        replay_returns_identical_body: z.literal(true),
      })
      .strict(),
  })
  .strict()

